1	package cli
2	
3	import (
4		"bytes"
5		"context"
6		"encoding/json"
7		"errors"
8		"fmt"
9		"io"
10		"os"
11		"os/signal"
12		"path/filepath"
13		"runtime"
14		"runtime/debug"
15		"strconv"
16		"strings"
17		"syscall"
18		"time"
19	
20		"github.com/entireio/entire-graph/internal/gitutil"
21		"github.com/entireio/entire-graph/internal/sem"
22		"github.com/entireio/entire-graph/internal/termsafe"
23	)
24	
25	type Options struct {
26		Version string
27		Env     EntireEnv
28		Stdout  io.Writer
29		Stderr  io.Writer
30		// Stdin is where `explain` reads a failing build's output from. It is the only command that takes
31		// piped input, because it is the only one whose question ("what are these names the build is
32		// complaining about") is asked by composing with another command rather than by naming a symbol.
33		Stdin io.Reader
34		// buildInfo overrides how the session replay reads this binary's build metadata. Unexported and
35		// nil in production (debug.ReadBuildInfo); tests set it to exercise specific producer identities.
36		buildInfo func() (*debug.BuildInfo, bool)
37	}
38	
39	func Execute(version string, args []string) error {
40		// Translate SIGINT/SIGTERM into context cancellation. Every Git subprocess
41		// is built with exec.CommandContext, so cancellation kills it; without this
42		// the default signal action ends only this process and leaves a running
43		// `git grep` child orphaned and burning CPU. After the first signal the
44		// default action is restored, so a second one still terminates at once.
45		// SIGKILL cannot be intercepted, and macOS has no parent-death signal, so a
46		// SIGKILLed parent still orphans its children until they next write to the
47		// closed stdout pipe (SIGPIPE).
48		ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
49		defer stop()
50		go func() {
51			<-ctx.Done()
52			stop()
53		}()
54		return Run(ctx, Options{
55			Version: version,
56			Env:     EnvFromOS(),
57			Stdout:  os.Stdout,
58			Stderr:  os.Stderr,
59			Stdin:   os.Stdin,
60		}, args)
61	}
62	
63	func Run(ctx context.Context, opts Options, args []string) error {
64		if opts.Version == "" {
65			opts.Version = "dev"
66		}
67		if opts.Stdout == nil {
68			opts.Stdout = io.Discard
69		}
70		if opts.Stderr == nil {
71			opts.Stderr = io.Discard
72		}
73	
74		if len(args) == 0 {
75			printHelp(opts.Stdout)
76			return nil
77		}
78	
79		// Per-command help: `entire graph <cmd> --help` prints that command's detail
80		// view and exits, without touching each runX. Only fires for commands that
81		// have a doc entry — which includes `help` itself, so `help --help` prints
82		// help's own detail view rather than the root listing. A bare `--help` has
83		// no command word and is handled above.
84		if doc, ok := findCommandDoc(args[0]); ok && wantsHelp(doc, args[1:]) {
85			renderCommandHelp(opts.Stdout, args[0])
86			return nil
87		}
88	
89		switch args[0] {
90		case "diff":
91			return runDiff(ctx, opts, args[1:])
92		case "commit":
93			return runCommit(ctx, opts, args[1:])
94		case "checkpoint":
95			return runCheckpoint(ctx, opts, args[1:])
96		case "analyze":
97			return runAnalyze(ctx, opts, args[1:])
98		case "doctor":
99			return runDoctor(ctx, opts, args[1:])
100		case "capabilities":
101			return runCapabilities(opts, args[1:])
102		case "snapshot":
103			return runProviderRecords(ctx, opts, args[1:], "snapshot")
104		case "snapshot-query":
105			return runSnapshotQuery(opts, args[1:])
106		case "symbols":
107			return runProviderRecords(ctx, opts, args[1:], "symbols")
108		case "edges":
109			return runProviderRecords(ctx, opts, args[1:], "edges")
110		case "query", "search":
111			return runSearch(ctx, opts, args[1:])
112		case "context":
113			return runContext(ctx, opts, args[1:])
114		case "index":
115			return runIndex(ctx, opts, args[1:])
116		case "health":
117			return runHealth(ctx, opts, args[1:])
118		case "def":
119			return runDef(ctx, opts, args[1:])
120		case "explain":
121			return runExplain(ctx, opts, args[1:])
122		case "neighbors":
123			return runNeighbors(ctx, opts, args[1:])
124		case "impact":
125			return runImpact(ctx, opts, args[1:])
126		case "verify":
127			return runVerify(ctx, opts, args[1:])
128		case "stats":
129			return runStats(ctx, opts, args[1:])
130		case "agent-guide":
131			return runAgentGuide(opts, args[1:])
132		case "init-agents":
133			return runInitAgents(opts, args[1:])
134		case "hook":
135			return runHook(opts, args[1:])
136		case "version", "--version", "-v":
137			if len(args) > 1 && args[1] == "--json" {
138				return json.NewEncoder(termsafe.NewJSONWriter(opts.Stdout)).Encode(map[string]string{
139					"provider":          sem.ProviderName,
140					"version":           opts.Version,
141					"identity_revision": sem.IdentityRevision,
142				})
143			}
144			fmt.Fprintln(opts.Stdout, opts.Version)
145			return nil
146		case "help", "--help", "-h":
147			printHelp(opts.Stdout)
148			return nil
149		default:
150			return fmt.Errorf("unknown command %q; run \"entire graph help\" to list commands", args[0])
151		}
152	}
153	
154	// printHelp renders the grouped root listing. Per-command detail lives in
155	// renderCommandHelp; both read from the commandDocs registry in help.go.
156	func printHelp(out io.Writer) {
157		renderRootHelp(out)
158	}
159	
160	func runDoctor(ctx context.Context, opts Options, args []string) error {
161		asJSON := false
162		var asserts []string
163		for index := 0; index < len(args); index++ {
164			switch args[index] {
165			case "--json":
166				asJSON = true
167			case "--assert":
168				// Repeatable: a harness usually drives more than one verb, and finding out about the
169				// second one only after the first has been fixed costs another whole run.
170				if index+1 >= len(args) {
171					return errors.New("doctor --assert needs a command line, for example --assert \"search --profile full\"")
172				}
173				index++
174				asserts = append(asserts, args[index])
175			default:
176				return errors.New("doctor accepts only --json and --assert \"<command line>\"")
177			}
178		}
179		// The assertions run FIRST and stop the report: a caller that asked whether this binary can
180		// serve its command line wants that answer, and printing an otherwise-healthy environment
181		// report above the failure buries it.
182		for _, spec := range asserts {
183			if err := checkPreflight(opts.Version, spec); err != nil {
184				return err
185			}
186		}
187		if len(asserts) > 0 && !asJSON {
188			for _, spec := range asserts {
189				fmt.Fprintf(opts.Stdout, "assert_ok=%q\n", spec)
190			}
191		}
192		report := map[string]any{
193			"provider":  sem.ProviderName,
194			"version":   opts.Version,
195			"no_egress": true,
196			"environment": map[string]string{
197				envCLIVersion:    valueOrUnset(opts.Env.CLIVersion),
198				envRepoRoot:      valueOrUnset(opts.Env.RepoRoot),
199				envPluginDataDir: valueOrUnset(opts.Env.PluginDataDir),
200			},
201			"phase_1_local_only": map[string]bool{
202				"fetch_remote_code":              false,
203				"download_grammars_or_assets":    false,
204				"upload_telemetry":               false,
205				"call_hosted_model_apis":         false,
206				"call_remote_embedding_provider": false,
207				"perform_network_discovery":      false,
208			},
209		}
210		if len(asserts) > 0 {
211			// Reaching here means every assertion parsed, so the JSON says so explicitly rather than
212			// leaving a caller to infer success from the absence of an error.
213			report["asserted_command_lines"] = asserts
214		}
215		if !asJSON {
216			fmt.Fprintf(opts.Stdout, "ENTIRE_CLI_VERSION=%s\n", valueOrUnset(opts.Env.CLIVersion))
217			fmt.Fprintf(opts.Stdout, "ENTIRE_REPO_ROOT=%s\n", valueOrUnset(opts.Env.RepoRoot))
218			fmt.Fprintf(opts.Stdout, "ENTIRE_PLUGIN_DATA_DIR=%s\n", valueOrUnset(opts.Env.PluginDataDir))
219			fmt.Fprintln(opts.Stdout, "no_egress=true")
220		}
221	
222		if opts.Env.PluginDataDir != "" {
223			if err := os.MkdirAll(opts.Env.PluginDataDir, 0o700); err != nil {
224				return fmt.Errorf("create plugin data dir: %w", err)
225			}
226			probe, err := os.CreateTemp(opts.Env.PluginDataDir, ".write-test-*")
227			if err != nil {
228				return fmt.Errorf("write plugin data dir: %w", err)
229			}
230			probeName := probe.Name()
231			if err := probe.Close(); err != nil {
232				return fmt.Errorf("close plugin data probe: %w", err)
233			}
234			if err := os.Remove(probeName); err != nil {
235				return fmt.Errorf("remove plugin data probe: %w", err)
236			}
237			report["plugin_data_dir"] = "writable"
238			if !asJSON {
239				fmt.Fprintln(opts.Stdout, "plugin_data_dir=writable")
240			}
241		}
242	
243		repo, err := resolveRepo(ctx, opts.Env, "")
244		if err == nil {
245			// Snapshot construction converts the resolved repository to an absolute,
246			// cleaned path before deriving either RepoRoot or RepoKey. Doctor is the
247			// preflight for that snapshot, so advertise the same spelling rather than
248			// the caller's possibly-relative ENTIRE_REPO_ROOT value.
249			repo, err = filepath.Abs(repo)
250		}
251		if err != nil {
252			report["repo_root"] = ""
253			report["repo_error"] = err.Error()
254			if asJSON {
255				return json.NewEncoder(termsafe.NewJSONWriter(opts.Stdout)).Encode(report)
256			}
257			fmt.Fprintf(opts.Stdout, "repo_root=%s\n", valueOrUnset(""))
258			fmt.Fprintf(opts.Stdout, "repo_error=%s\n", err)
259			return nil
260		}
261		report["repo_root"] = repo
262		// The repo_key and schema_version this binary WILL use are part of the
263		// doctor report so a consumer can verify the seam contract up front. Brain
264		// runs doctor before every snapshot; discovering a repo_key rule mismatch or
265		// an unsupported schema major here costs milliseconds, whereas discovering
266		// it from the finished snapshot costs the whole (up to 30 minute) run.
267		report["repo_key"] = sem.RepoKey(ctx, repo)
268		report["schema_version"] = sem.SchemaVersion
269		if asJSON {
270			return json.NewEncoder(termsafe.NewJSONWriter(opts.Stdout)).Encode(report)
271		}
272		fmt.Fprintf(opts.Stdout, "repo_root=%s\n", repo)
273		return nil
274	}
275	
276	func runCapabilities(opts Options, args []string) error {
277		if len(args) != 1 || args[0] != "--json" {
278			return errors.New("capabilities requires --json")
279		}
280		return json.NewEncoder(termsafe.NewJSONWriter(opts.Stdout)).Encode(sem.Capabilities())
281	}
282	
283	func runProviderRecords(ctx context.Context, opts Options, args []string, mode string) error {
284		flags, rest, err := parseProviderFlags(args)
285		if err != nil {
286			return err
287		}
288		if len(rest) != 0 {
289			return unexpectedArgumentsError(mode, opts.Version, rest)
290		}
291		if mode != "snapshot" && mode != "symbols" && mode != "edges" {
292			return fmt.Errorf("unknown provider record mode %q", mode)
293		}
294		filterActive := flags.To != "" || flags.From != "" || len(flags.Relation) > 0
295		compact := flags.Format == "compact-ndjson"
296		scip := flags.Format == "scip"
297		if flags.Format != "ndjson" && !compact && !scip {
298			if mode == "snapshot" {
299				return fmt.Errorf("%s requires --format ndjson, compact-ndjson, or scip", mode)
300			}
301			return fmt.Errorf("%s requires --format ndjson", mode)
302		}
303		if (compact || scip) && mode != "snapshot" {
304			return fmt.Errorf("--format %s is only valid for snapshot", flags.Format)
305		}
306		if (compact || scip) && filterActive {
307			return fmt.Errorf("--format %s requires a complete snapshot; remove --to/--from/--relation", flags.Format)
308		}
309		if scip && flags.Progress {
310			return errors.New("--format scip cannot be combined with --progress; stderr is reserved for the JSON omission note")
311		}
312		repo, err := resolveRepo(ctx, opts.Env, flags.Repo)
313		if err != nil {
314			return err
315		}
316		profile, err := parseProfile(flags.Profile)
317		if err != nil {
318			return err
319		}
320		options := sem.ProviderSnapshotOptions{
321			NoNetwork:    flags.NoNetwork,
322			Worktree:     flags.Worktree,
323			IgnoreFiles:  flags.IgnoreFiles,
324			IncludeFiles: flags.IncludeFiles,
325			Profile:      profile,
326		}
327		if flags.Progress {
328			options.Progress = func(event sem.ProgressEvent) {
329				fmt.Fprintf(opts.Stderr, "graph progress phase=%s files=%d/%d symbols=%d relations=%d heap=%d rss=%d elapsed=%s\n",
330					event.Phase,
331					event.FilesDone,
332					event.FilesTotal,
333					event.Symbols,
334					event.Relations,
335					event.HeapAlloc,
336					event.MaxRSSBytes,
337					event.Elapsed.Round(time.Millisecond),
338				)
339			}
340		}
341		// Native and compact encoders stream records directly. SCIP must collect the
342		// complete graph before writing its single protobuf Index message.
343		var scipEncoder *sem.SCIPSnapshotEncoder
344		newRecordEncoder := func(out io.Writer) func(any) error {
345			if scip {
346				// NOT wrapped. `--format scip` writes a binary protobuf Index, and the C1
347				// rewrite is defined over a TEXT stream: it would rewrite any 0xc2 0x8X
348				// pair the wire format happens to contain -- a varint, a length prefix, a
349				// UTF-8 name -- into six ASCII bytes, and the result no longer parses as
350				// an Index at all. A hostile pathname in this stream reaches a terminal
351				// only after a consumer has decoded the protobuf and chosen to render it,
352				// which is that consumer's escape to apply, not this encoder's.
353				scipEncoder = sem.NewSCIPSnapshotEncoder(out, "")
354				return scipEncoder.Encode
355			}
356			// Wrapped once here rather than in either branch below: both encoders write
357			// repository-controlled pathnames and entity names, and a snapshot carries no
358			// source text, so a hostile PATHNAME is the only C1 these streams can hold.
359			out = termsafe.NewJSONWriter(out)
360			if compact {
361				return sem.NewCompactSnapshotEncoder(out).Encode
362			}
363			encoder := json.NewEncoder(out)
364			encoder.SetEscapeHTML(false) // match json.Marshal used elsewhere (no < escaping)
365			return encoder.Encode
366		}
367		encodeRecord := newRecordEncoder(opts.Stdout)
368		if scipEncoder != nil {
369			// The version is read inside the snapshot build, through the reader that
370			// is already validated, bounded and pinned to this snapshot's revision.
371			// Reading it here instead would run Git before the metadata preflight and
372			// touch the filesystem without the provider's guards.
373			options.ProjectVersion = scipEncoder.SetProjectVersion
374		}
375	
376		// Targeted edge query: when --to/--from/--relation is set, emit only matching
377		// relations (plus header/summary), never files/symbols. Turns "callers of X"
378		// into a tiny reply instead of dumping the whole graph for the caller to grep.
379		// Streaming-safe: idMatches keys off the stable ID's trailing name segment, so
380		// no in-memory symbol table is needed. Only meaningful in edges/snapshot modes.
381		// Capture the summary as it streams past so we can loudly warn on a partial
382		// parse. Without this the CLI discards the summary and a run that silently
383		// parsed only a fraction of the repo (e.g. a mis-scoped subdir) looks clean.
384		var summary *sem.SnapshotSummary
385		var snapshotHeader sem.SnapshotHeader
386		capture := func(record any) {
387			switch r := record.(type) {
388			case sem.SnapshotHeader:
389				snapshotHeader = r
390			case sem.SnapshotSummary:
391				s := r
392				summary = &s
393			}
394		}
395	
396		if filterActive && mode == "symbols" {
397			return fmt.Errorf("--to/--from/--relation filter relations; use `edges` (not `symbols`)")
398		}
399		// Serve from the committed-record cache when possible. The cache is keyed on
400		// the exact HEAD commit and tree, the mode, and output-affecting options, so
401		// an unchanged HEAD skips the expensive re-index. It is deliberately bypassed
402		// for --worktree, whose source cannot be pinned to one tree, and for SCIP.
403		//
404		// A targeted edge query (--to/--from/--relation) reads and fills the SAME
405		// entry an unfiltered `edges` run does and filters it, because its output is
406		// exactly that stream's header, matching relations and summary. It used to
407		// take no cache at all, so `--cache-dir` was accepted and silently ignored and
408		// every "callers of X" rebuilt the whole graph.
409		cacheMode := mode
410		if filterActive {
411			cacheMode = "edges"
412		} else if compact {
413			cacheMode = "snapshot:compact-ndjson-v1"
414		}
415		cacheDir := resolveCacheDir(flags.CacheDir, opts.Env.PluginDataDir)
416		useCache := !flags.DisableCache && !flags.Worktree && !scip && cacheDir != ""
417		var commit, tree string
418		cacheContext := ctx
419		if useCache {
420			var validationErr error
421			cacheContext, validationErr = sem.WithGitMetadataValidationForSetup(ctx, repo)
422			if validationErr != nil {
423				// Cache probing is optional and runs before provider construction. Unsafe
424				// metadata disables the probe; the provider below selects its warned,
425				// filesystem-only fallback without starting Git.
426				useCache = false
427			}
428		}
429		if useCache {
430			if c, t, headErr := gitutil.HeadCommitAndTree(cacheContext, repo); headErr == nil && c != "" && t != "" {
431				commit = c
432				tree = t
433			} else {
434				useCache = false
435			}
436		}
437		var recordsCache *sem.ProviderRecordsCacheTransaction
438		if useCache {
439			recordsCache, err = sem.BeginProviderRecordsCache(cacheContext, repo, opts.Version, commit, tree, cacheMode, cacheDir, options)
440			if err != nil {
441				// Cache setup is optional. The uncached stream below will surface any
442				// policy-input error that also prevents a correct build.
443				recordsCache = nil
444			} else {
445				// Pin matcher construction to the exact policy bytes that keyed this
446				// lookup, and carry the same transaction through storage below.
447				options = recordsCache.Options()
448			}
449		}
450		// The spool is created only on a cache miss and consumed by Store; the
451		// deferred Abandon covers every other exit (stream error, provenance
452		// refusal upstream of Store) so a failed run leaves no temporary behind.
453		var spool *sem.ProviderRecordsSpool
454		defer func() { spool.Abandon() }()
455	
456		if filterActive {
457			reportMatched := func(matched int) {
458				fmt.Fprintf(opts.Stderr, "graph: %d edge(s) matched (--to=%q --from=%q --relation=%s)\n",
459					matched, flags.To, flags.From, strings.Join(flags.Relation, ","))
460			}
461			if recordsCache != nil {
462				if records, cachedSummary, hit := recordsCache.Load(); hit {
463					filtered, matched, ok := filterCachedEdgeRecords(records, flags)
464					if ok {
465						// Same wrap as the unfiltered hit below: escaping is idempotent, and an
466						// entry written before the C1 rule must not reach the terminal raw.
467						if _, err := termsafe.NewJSONWriter(opts.Stdout).Write(filtered); err != nil {
468							return err
469						}
470						warnIfPartial(opts.Stderr, flags.Worktree, cachedSummary)
471						reportMatched(matched)
472						return nil
473					}
474				}
475			}
476			// On a miss, the unfiltered edges stream is teed into the cache entry while
477			// only the matching relations reach stdout, so the next targeted query on
478			// this tree, whatever it asks, is a hit.
479			var cacheRecord func(any) error
480			if spool = beginRecordsSpool(recordsCache, opts.Stderr); spool != nil {
481				cacheRecord = newRecordEncoder(spool)
482			}
483			var matched int
484			if err := sem.StreamSnapshot(ctx, repo, opts.Version, options, func(record any) error {
485				capture(record)
486				if cacheRecord != nil && includeRecord("edges", record) {
487					if err := cacheRecord(record); err != nil {
488						return err
489					}
490				}
491				switch r := record.(type) {
492				case sem.RelationRecord:
493					if !relationMatches(r, flags) {
494						return nil
495					}
496					matched++
497					return encodeRecord(r)
498				case sem.FileRecord, sem.ExternalRecord, sem.SymbolRecord:
499					return nil // suppressed for a targeted edge query
500				default: // header, summary
501					return encodeRecord(record)
502				}
503			}); err != nil {
504				return err
505			}
506			warnIfPartial(opts.Stderr, flags.Worktree, summary)
507			reportMatched(matched)
508			if spool != nil {
509				// Best effort: a failed cache write never fails the command, but it is
510				// said once on stderr rather than silently costing a re-parse per run.
511				if err := recordsCache.Store(spool, summary, snapshotHeader); err != nil {
512					fmt.Fprintf(opts.Stderr, "graph: provider records cache not stored: %v\n", err)
513				}
514				spool = nil
515			}
516			return nil
517		}
518	
519		if recordsCache != nil {
520			if records, cachedSummary, hit := recordsCache.Load(); hit {
521				// Replayed bytes need the same wrap the encoder below gets. This path does
522				// not go through encodeRecord at all, so a cache entry written before the
523				// C1 rule existed — or by any build that predates it — would stream the
524				// repository's raw control straight to the terminal on every hit. Escaping
525				// is idempotent, so a clean entry passes through unchanged.
526				if _, err := termsafe.NewJSONWriter(opts.Stdout).Write(records); err != nil {
527					return err
528				}
529				warnIfPartial(opts.Stderr, flags.Worktree, cachedSummary)
530				return nil
531			}
532		}
533	
534		// On a miss, tee the serialized record stream into the disk spool so we can
535		// persist it after a successful run without a second pass over the graph.
536		// The spool gzips to a temporary file in the cache directory, so the tee's
537		// memory stays constant whatever the graph's size: the cache is on by
538		// default, and an in-memory capture here once held the command's ENTIRE
539		// output — or, capped, silently stored nothing on exactly the large
540		// repositories the cache matters most for.
541		if spool = beginRecordsSpool(recordsCache, opts.Stderr); spool != nil {
542			encodeRecord = newRecordEncoder(io.MultiWriter(opts.Stdout, spool))
543		}
544		if err := sem.StreamSnapshot(ctx, repo, opts.Version, options, func(record any) error {
545			capture(record)
546			if !includeRecord(mode, record) {
547				return nil
548			}
549			return encodeRecord(record)
550		}); err != nil {
551			return err
552		}
553		if scipEncoder != nil {
554			if err := writeSCIPOmissionNote(opts.Stderr, scipOmissionNoteWithSummary(scipEncoder.OmissionNote(), summary)); err != nil {
555				return err
556			}
557		} else {
558			warnIfPartial(opts.Stderr, flags.Worktree, summary)
559		}
560		if spool != nil {
561			// Best effort: a failed cache write never fails the command, but it is
562			// said once on stderr rather than silently costing a re-parse per run.
563			if err := recordsCache.Store(spool, summary, snapshotHeader); err != nil {
564				fmt.Fprintf(opts.Stderr, "graph: provider records cache not stored: %v\n", err)
565			}
566			spool = nil
567		}
568		return nil
569	}
570	
571	// beginRecordsSpool opens the disk spool a cold run tees its records into, or
572	// returns nil (after one stderr line) when the cache cannot take them. The
573	// spool writes ALWAYS report success to the io.MultiWriter that also feeds
574	// stdout only in the sense that a working spool never short-writes; a spool
575	// that cannot even open is dropped here so no cache failure can abort the
576	// stream the command exists to produce. Its predecessor buffered the capture
577	// in memory under a 64MB cap and silently stored nothing past it, so every
578	// repository whose snapshot outgrew the cap re-parsed on each run.
579	func beginRecordsSpool(recordsCache *sem.ProviderRecordsCacheTransaction, stderr io.Writer) *sem.ProviderRecordsSpool {
580		spool, err := recordsCache.NewSpool()
581		if err != nil {
582			fmt.Fprintf(stderr, "graph: provider records cache unavailable: %v\n", err)
583			return nil
584		}
585		return spool
586	}
587	
588	func scipOmissionNoteWithSummary(note sem.SCIPOmissionNote, summary *sem.SnapshotSummary) sem.SCIPOmissionNote {
589		if summary == nil {
590			return note
591		}
592		note.WarningCount = len(summary.Warnings)
593		note.PartialFailureCount = len(summary.PartialFailures)
594		// The records themselves, not just how many. SCIP cannot represent a file
595		// that was discovered but not parsed, so without these the note is the only
596		// place that information could have survived, and it was being reduced to an
597		// integer.
598		note.PartialFailures = summary.PartialFailures
599		// Which languages were only inventoried, so a consumer can scope trust per
600		// language the way the feed contract expects.
601		note.LanguageTiers = summary.LanguageTiers
602		level := summary.Stats.CompletenessLevel
603		if level == "" || level == "ok" {
604			return note
605		}
606		note.PartialSnapshot = true
607		note.CompletenessLevel = level
608		return note
609	}
610	
611	func writeSCIPOmissionNote(w io.Writer, note sem.SCIPOmissionNote) error {
612		// The note is the one TEXT stream `--format scip` writes, and it is written to
613		// a terminal. It is wrapped for the same structural reason every other machine
614		// encoder here is: a sink left unwrapped is the one the next field added to
615		// this record forgets about.
616		encoder := json.NewEncoder(termsafe.NewJSONWriter(w))
617		encoder.SetEscapeHTML(false)
618		return encoder.Encode(note)
619	}
620	
621	// warnIfPartial prints a loud stderr banner when the snapshot did not fully cover
622	// the repository, so a silent partial parse (the #1 sharp edge: running in a
623	// mis-scoped subdir without --worktree, which indexes only a stray config file
624	// and reports "ok") becomes impossible to miss. Silent on a clean "ok" run.
625	func warnIfPartial(w io.Writer, worktree bool, s *sem.SnapshotSummary) {
626		if s == nil {
627			return
628		}
629		level := s.Stats.CompletenessLevel
630		if level == "" || level == "ok" {
631			return
632		}
633		fmt.Fprintf(w, "\n⚠️  graph is %s: parsed %d/%d files, %d symbols, %d relations (languages: %s).\n",
634			strings.ToUpper(level), s.Stats.ParsedFiles, s.Stats.Files, s.Stats.Symbols,
635			s.Stats.Relations, strings.Join(s.Languages, ", "))
636		switch {
637		case s.Stats.Files <= 2 && !worktree:
638			fmt.Fprintf(w, "   Only %d file(s) were discovered — you may be indexing a subdirectory or an\n"+
639				"   unexpected commit. Run from the repo root, or pass --worktree to index the\n"+
640				"   working tree instead of HEAD.\n", s.Stats.Files)
641		case s.Stats.ParsedFiles*2 < s.Stats.Files:
642			fmt.Fprintf(w, "   Over half the discovered files were not parsed (unsupported language or\n"+
643				"   parse errors). Graph queries will miss code in those files.\n")
644		default:
645			fmt.Fprintf(w, "   The graph is incomplete; treat query results as partial.\n")
646		}
647	}
648	
649	// filterCachedEdgeRecords applies a targeted edge query to a cached `edges`
650	// stream, which holds only the header, relations and summary (includeRecord):
651	// relation lines pass when they match and everything else passes, exactly as
652	// the uncached targeted stream decides. Lines are passed through as stored, so a
653	// hit is byte-identical to the miss that wrote it. A line that does not decode reports !ok, and the caller
654	// rebuilds rather than trusting an entry it cannot read.
655	func filterCachedEdgeRecords(records []byte, flags providerFlags) ([]byte, int, bool) {
656		var filtered bytes.Buffer
657		matched := 0
658		for len(records) > 0 {
659			line := records
660			if index := bytes.IndexByte(records, '\n'); index >= 0 {
661				line, records = records[:index+1], records[index+1:]
662			} else {
663				records = nil
664			}
665			if len(bytes.TrimSpace(line)) == 0 {
666				continue
667			}
668			var kind sem.ProviderRecord
669			if err := json.Unmarshal(line, &kind); err != nil {
670				return nil, 0, false
671			}
672			if kind.RecordType == "relation" {
673				var relation sem.RelationRecord
674				if err := json.Unmarshal(line, &relation); err != nil {
675					return nil, 0, false
676				}
677				if !relationMatches(relation, flags) {
678					continue
679				}
680				matched++
681			}
682			filtered.Write(line)
683		}
684		return filtered.Bytes(), matched, true
685	}
686	
687	// includeRecord filters streamed records for the symbols and edges modes, which
688	// emit a subset of the full snapshot.
689	func includeRecord(mode string, record any) bool {
690		switch record.(type) {
691		case sem.FileRecord, sem.ExternalRecord:
692			return mode == "snapshot"
693		case sem.SymbolRecord:
694			return mode == "snapshot" || mode == "symbols"
695		case sem.RelationRecord:
696			return mode == "snapshot" || mode == "edges"
697		default: // header, summary
698			return true
699		}
700	}
701	
702	// defaultMaxSeconds is the wall-clock budget applied to diff/commit/analyze
703	// when --max-seconds is not given. Large repos with hot changed names can
704	// otherwise grind for many minutes and produce nothing; with the budget the
705	// command stops cleanly at the limit and emits the partial result plus
706	// machine-readable W_ANALYSIS_BUDGET_EXCEEDED warnings. --max-seconds 0
707	// disables the budget.
708	const defaultMaxSeconds = 120
709	
710	type commonFlags struct {
711		Repo     string
712		JSON     bool
713		Progress bool
714		// MaxSeconds is the overall analysis budget in seconds; -1 means the flag
715		// was not given (commands apply their default), 0 means unlimited.
716		MaxSeconds int
717	}
718	
719	type providerFlags struct {
720		Repo         string
721		Format       string
722		Profile      string
723		NoNetwork    bool
724		Worktree     bool
725		Progress     bool
726		IgnoreFiles  []string
727		IncludeFiles []string
728		// Targeted edge filters (edges mode). When any is set the command emits only
729		// the matching relation records (plus header/summary) instead of the whole
730		// graph, so "callers of X" is a tiny reply rather than a 50MB dump that the
731		// caller then greps client-side. --to/--from match a symbol by full stable ID
732		// or by trailing name segment (IDs are `...:kind:name`); --relation is one or
733		// more edge types (comma-separated, case-insensitive), e.g. CALLS,REFERENCES.
734		To       string
735		From     string
736		Relation []string
737		// CacheDir/DisableCache control the committed-record cache. Empty CacheDir
738		// falls back to ENTIRE_PLUGIN_DATA_DIR; --no-cache disables it entirely.
739		CacheDir     string
740		DisableCache bool
741	}
742	
743	// idMatches reports whether a stable symbol ID matches a user-supplied selector:
744	// either the exact ID, or a trailing name segment (IDs end `...:kind:name`, so
745	// `getConfPath` or `function:getConfPath` both select it). Streaming-safe — no
746	// symbol table needed.
747	func idMatches(id, sel string) bool {
748		return id == sel || strings.HasSuffix(id, ":"+sel)
749	}
750	
751	// relationMatches applies the --to/--from/--relation predicate to one edge.
752	func relationMatches(r sem.RelationRecord, f providerFlags) bool {
753		if f.To != "" && !idMatches(r.ToID, f.To) {
754			return false
755		}
756		if f.From != "" && !idMatches(r.FromID, f.From) {
757			return false
758		}
759		if len(f.Relation) > 0 {
760			t := strings.ToUpper(r.Type)
761			hit := false
762			for _, want := range f.Relation {
763				if t == want {
764					hit = true
765					break
766				}
767			}
768			if !hit {
769				return false
770			}
771		}
772		return true
773	}
