775	// parseProfile validates the --profile value. Empty defaults to full.
776	func parseProfile(value string) (sem.Profile, error) {
777		switch value {
778		case "", "full":
779			return sem.ProfileFull, nil
780		case "fast":
781			return sem.ProfileFast, nil
782		case "syntax-only":
783			return sem.ProfileSyntaxOnly, nil
784		default:
785			return "", fmt.Errorf("unknown --profile %q (want full, fast, or syntax-only)", value)
786		}
787	}
