789	func parseProviderFlags(args []string) (providerFlags, []string, error) {
790		flags := providerFlags{Format: "ndjson"}
791		var rest []string
792		for i := 0; i < len(args); i++ {
793			switch args[i] {
794			case "--repo":
795				i++
796				if i >= len(args) {
797					return flags, nil, errors.New("--repo requires a value")
798				}
799				flags.Repo = args[i]
800			case "--format":
801				i++
802				if i >= len(args) {
803					return flags, nil, errors.New("--format requires a value")
804				}
805				flags.Format = args[i]
806			case "--profile":
807				i++
808				if i >= len(args) {
809					return flags, nil, errors.New("--profile requires a value")
810				}
811				flags.Profile = args[i]
812			case "--no-network":
813				flags.NoNetwork = true
814			case "--worktree":
815				flags.Worktree = true
816			case "--progress":
817				flags.Progress = true
818			case "--ignore-file":
819				i++
820				if i >= len(args) {
821					return flags, nil, errors.New("--ignore-file requires a value")
822				}
823				flags.IgnoreFiles = append(flags.IgnoreFiles, args[i])
824			case "--include-file":
825				i++
826				if i >= len(args) {
827					return flags, nil, errors.New("--include-file requires a value")
828				}
829				flags.IncludeFiles = append(flags.IncludeFiles, args[i])
830			case "--cache-dir":
831				i++
832				if i >= len(args) {
833					return flags, nil, errors.New("--cache-dir requires a value")
834				}
835				flags.CacheDir = args[i]
836			case "--no-cache":
837				flags.DisableCache = true
838			case "--to":
839				i++
840				if i >= len(args) {
841					return flags, nil, errors.New("--to requires a value")
842				}
843				flags.To = args[i]
844			case "--from":
845				i++
846				if i >= len(args) {
847					return flags, nil, errors.New("--from requires a value")
848				}
849				flags.From = args[i]
850			case "--relation":
851				i++
852				if i >= len(args) {
853					return flags, nil, errors.New("--relation requires a value")
854				}
855				for _, part := range strings.Split(args[i], ",") {
856					if part = strings.ToUpper(strings.TrimSpace(part)); part != "" {
857						flags.Relation = append(flags.Relation, part)
858					}
859				}
860			default:
861				rest = append(rest, args[i])
862			}
863		}
864		return flags, rest, nil
865	}
866	
867	func parseCommonFlags(args []string) (commonFlags, []string, error) {
868		flags := commonFlags{MaxSeconds: -1}
869		var rest []string
870		for i := 0; i < len(args); i++ {
871			arg := args[i]
872			switch arg {
873			case "--json":
874				flags.JSON = true
875			case "--progress":
876				flags.Progress = true
877			case "--max-seconds":
878				i++
879				if i >= len(args) {
880					return flags, nil, errors.New("--max-seconds requires a value")
881				}
882				seconds, err := strconv.Atoi(args[i])
883				if err != nil || seconds < 0 {
884					return flags, nil, fmt.Errorf("--max-seconds requires a non-negative integer, got %q", args[i])
885				}
886				flags.MaxSeconds = seconds
887			case "--repo":
888				i++
889				if i >= len(args) {
890					return flags, nil, errors.New("--repo requires a value")
891				}
892				flags.Repo = args[i]
893			case "--":
894				rest = append(rest, args[i+1:]...)
895				return flags, rest, nil
896			default:
897				rest = append(rest, arg)
898			}
899		}
900		return flags, rest, nil
901	}
902	
903	func runCommit(ctx context.Context, opts Options, args []string) error {
904		flags, rest, err := parseCommonFlags(args)
905		if err != nil {
906			return err
907		}
908		rev := "HEAD"
909		if len(rest) > 0 {
910			rev = rest[0]
911		}
912		if len(rest) > 1 {
913			return errors.New("commit accepts at most one revision")
914		}
915		if err := validateRevision("commit", rev); err != nil {
916			return err
917		}
918		repo, err := resolveRepo(ctx, opts.Env, flags.Repo)
919		if err != nil {
920			return err
921		}
922		if err := requireRangeRepoRoot(ctx, repo, "commit"); err != nil {
923			return err
924		}
925		base, err := gitutil.FirstParent(ctx, repo, rev)
926		if err != nil {
927			return err
928		}
929		return analyzeAndPrint(ctx, opts, repo, base, rev, nil, flags)
930	}
931	
932	func runCheckpoint(ctx context.Context, opts Options, args []string) error {
933		flags, rest, err := parseCommonFlags(args)
934		if err != nil {
935			return err
936		}
937		if flags.Progress {
938			return errors.New("checkpoint does not support --progress")
939		}
940		if flags.MaxSeconds >= 0 {
941			return errors.New("checkpoint does not support --max-seconds")
942		}
943		if len(rest) != 1 {
944			return errors.New("checkpoint requires exactly one checkpoint ID")
945		}
946		repo, err := resolveRepo(ctx, opts.Env, flags.Repo)
947		if err != nil {
948			return err
949		}
950		if err := requireRangeRepoRoot(ctx, repo, "checkpoint"); err != nil {
951			return err
952		}
953		result, err := sem.AnalyzeCheckpoint(ctx, repo, rest[0])
954		if err != nil {
955			return err
956		}
957		return printResult(opts.Stdout, result, flags.JSON, opts.Version)
958	}
959	
960	func runAnalyze(ctx context.Context, opts Options, args []string) error {
961		return runDiff(ctx, opts, args)
962	}
963	
964	// validateRevision rejects a revision value that Git would read as an option instead.
965	//
966	// Every revision this package accepts is eventually spliced into a git argv — `git diff -z
967	// --raw --find-renames <base> <head> --` in gitutil.ChangedFiles, `git rev-parse
968	// <rev>^` in gitutil.FirstParent, `git show <rev>^{tree}:<path>` in gitutil.ShowFile. Git
969	// parses options anywhere ahead of `--`, so a value beginning with '-' stops being a revision
970	// and becomes a flag of the command it lands in: `diff --base '--output=FILE'` exited 0 having
971	// truncated FILE and replaced it with git's own name-status output (CWE-88), and `commit
972	// '--output=FILE'` reached the same argv because `git rev-parse '--output=FILE^'` does not
973	// fail first.
974	//
975	// Refusing at the boundary costs nothing legitimate. Values beginning with "--" are always
976	// Git options; bare "-" is ambiguous with git's path/option syntax. Single-hyphen refs such as
977	// "-foo" are valid and must not be rejected here — gitutil uses "--end-of-options" elsewhere
978	// when splicing user paths into git argv.
979	func validateRevision(name, rev string) error {
980		if rev == "" {
981			return fmt.Errorf("%s requires a revision", name)
982		}
983		if strings.HasPrefix(rev, "--") {
984			return fmt.Errorf("%s %q is not a revision: a revision cannot begin with %q, which Git would read as an option", name, rev, "--")
985		}
986		if rev == "-" {
987			return fmt.Errorf("%s %q is not a revision: bare %q is ambiguous with git's path/option syntax", name, rev, "-")
988		}
989		if strings.ContainsRune(rev, '\x00') {
990			return fmt.Errorf("%s %q is not a revision: a revision cannot contain a NUL byte", name, rev)
991		}
992		return nil
993	}
994	
995	// diffFlags is the parsed argument set for `diff` and its `analyze` alias.
996	type diffFlags struct {
997		common commonFlags
998		base   string
999		head   string
1000		paths  []string
1001	}
1002	
1003	// parseDiffFlags parses `diff`/`analyze` arguments, returning any flag-shaped argument it does
1004	// not recognize separately from the path filters, so the caller can reject it the way every
1005	// other verb does.
1006	//
1007	// Separating the two is the point. The parsing used to live inline in runDiff, whose default
1008	// branch filed EVERY unrecognized token under paths — so `diff --jsonn` exited 0 having filtered
1009	// the diff to a path that does not exist, and printed "No semantic entity changes detected". A
1010	// mistyped flag was answered with a confident empty result, which for a verb whose whole job is
1011	// telling you what changed is the worst possible way to be wrong.
1012	//
1013	// Paths that genuinely look like flags still work: that is what the documented `-- path...`
1014	// separator is for.
1015	// diffValueFlags are the `diff`/`analyze` flags whose value is the NEXT argument: the two
1016	// parseCommonFlags consumes and the two the loop below does. It exists only for the separator scan
1017	// above, which runs before either parser and so cannot ask them.
1018	var diffValueFlags = map[string]bool{
1019		"--repo":        true,
1020		"--max-seconds": true,
1021		"--base":        true,
1022		"--head":        true,
1023	}
1024	
1025	func parseDiffFlags(args []string) (diffFlags, []string, error) {
1026		parsed := diffFlags{base: "HEAD~1", head: "HEAD"}
1027	
1028		// Split on `--` here rather than letting parseCommonFlags consume it: that function flattens
1029		// everything after the separator into rest, which would leave a literal path named `--base`
1030		// indistinguishable from the real flag.
1031		//
1032		// Skipping each value-taking flag's value is what keeps `--` a separator rather than a pattern:
1033		// `diff --repo --` addresses a repository directory literally named `--`, and a raw scan cut the
1034		// arguments off in front of it and failed with "--repo requires a value" — with no `--repo=--`
1035		// spelling to fall back on, because these parsers accept no `=` form.
1036		flagArgs, literalPaths := args, []string(nil)
1037		for i := 0; i < len(args); i++ {
1038			if diffValueFlags[args[i]] {
1039				i++
1040				continue
1041			}
1042			if args[i] == "--" {
1043				flagArgs, literalPaths = args[:i], args[i+1:]
1044				break
1045			}
1046		}
1047	
1048		common, rest, err := parseCommonFlags(flagArgs)
1049		if err != nil {
1050			return diffFlags{}, nil, err
1051		}
1052		parsed.common = common
1053	
1054		var unknown []string
1055		for i := 0; i < len(rest); i++ {
1056			switch rest[i] {
1057			case "--base":
1058				i++
1059				if i >= len(rest) {
1060					return diffFlags{}, nil, errors.New("--base requires a value")
1061				}
1062				if err := validateRevision("--base", rest[i]); err != nil {
1063					return diffFlags{}, nil, err
1064				}
1065				parsed.base = rest[i]
1066			case "--head":
1067				i++
1068				if i >= len(rest) {
1069					return diffFlags{}, nil, errors.New("--head requires a value")
1070				}
1071				if err := validateRevision("--head", rest[i]); err != nil {
1072					return diffFlags{}, nil, err
1073				}
1074				parsed.head = rest[i]
1075			default:
1076				if strings.HasPrefix(rest[i], "-") && rest[i] != "-" {
1077					unknown = append(unknown, rest[i])
1078					continue
1079				}
1080				parsed.paths = append(parsed.paths, rest[i])
1081			}
1082		}
1083		parsed.paths = append(parsed.paths, literalPaths...)
1084		return parsed, unknown, nil
1085	}
1086	
1087	func runDiff(ctx context.Context, opts Options, args []string) error {
1088		parsed, unknown, err := parseDiffFlags(args)
1089		if err != nil {
1090			return err
1091		}
1092		if len(unknown) != 0 {
1093			return unexpectedArgumentsError("diff", opts.Version, unknown)
1094		}
1095	
1096		repo, err := resolveRepo(ctx, opts.Env, parsed.common.Repo)
1097		if err != nil {
1098			return err
1099		}
1100		if err := requireRangeRepoRoot(ctx, repo, "diff"); err != nil {
1101			return err
1102		}
1103		return analyzeAndPrint(ctx, opts, repo, parsed.base, parsed.head, parsed.paths, parsed.common)
1104	}
1105	
1106	func requireRangeRepoRoot(ctx context.Context, repo, command string) error {
1107		if err := sem.EnsureGitMetadataSafeForSubprocess(repo); err != nil {
1108			return err
1109		}
1110		prefix, err := gitutil.RepoPrefix(ctx, repo)
1111		if err != nil {
1112			return err
1113		}
1114		if prefix != "" {
1115			return fmt.Errorf("%s requires --repo to name the checkout root; subdirectories are not supported", command)
1116		}
1117		return nil
1118	}
1119	
1120	func resolveRepo(ctx context.Context, env EntireEnv, explicit string) (string, error) {
1121		if explicit != "" {
1122			return explicit, nil
1123		}
1124		if env.RepoRoot != "" {
1125			return env.RepoRoot, nil
1126		}
1127		if os.Getenv("GIT_CEILING_DIRECTORIES") != "" {
1128			// Git canonicalizes ceiling entries before discovery. A caller-controlled
1129			// Windows UNC entry can therefore perform network I/O before Git looks for
1130			// repository metadata. Apply the boundary in-process with the provider's
1131			// same-volume resolver and never pass its raw path list to a subprocess.
1132			if root, ok := discoverImplicitCheckoutRoot("."); ok {
1133				return root, nil
1134			}
1135			return "", errors.New("no Git repository found below GIT_CEILING_DIRECTORIES")
1136		}
1137		if err := sem.EnsureGitMetadataSafeForSubprocess("."); err != nil {
1138			// Preserve the provider's warned filesystem-only fallback without asking
1139			// Git to discover the checkout. Analyze entry points apply their own strict
1140			// guard before resolving revisions.
1141			if root, ok := discoverImplicitCheckoutRoot("."); ok {
1142				return root, nil
1143			}
1144			return ".", nil
1145		}
1146		return gitutil.RepoRoot(ctx, ".")
1147	}
1148	
1149	// discoverImplicitCheckoutRoot applies an inherited ceiling without a Git
1150	// subprocess. With no usable ceiling it keeps the established two-spelling
1151	// filesystem fallback. Git canonicalizes entries before the first empty list
1152	// element, while an empty element promises that subsequent entries contain no
1153	// symlinks and can stay lexical. Canonicalization uses the provider's guarded
1154	// same-volume walk, which refuses off-volume and UNC redirects before probing
1155	// them. Unresolvable entries are discarded just as Git discards them.
1156	func discoverImplicitCheckoutRoot(dir string) (string, bool) {
1157		abs, err := filepath.Abs(dir)
1158		if err != nil {
1159			return "", false
1160		}
1161		abs = filepath.Clean(abs)
1162	
1163		type ceilingEntry struct {
1164			path         string
1165			canonicalize bool
1166		}
1167		var entries []ceilingEntry
1168		canonicalize := true
1169		for _, entry := range strings.Split(os.Getenv("GIT_CEILING_DIRECTORIES"), string(os.PathListSeparator)) {
1170			// Git documents ceiling entries as absolute paths. The first empty
1171			// entry disables canonicalization for every subsequent entry.
1172			if entry == "" {
1173				canonicalize = false
1174				continue
1175			}
1176			absoluteEntry, absolute := sem.GitAbsolutePath(abs, entry)
1177			if !absolute {
1178				if sem.GitAbsolutePathNeedsFailClosed(entry) {
1179					return "", false
1180				}
1181				continue
1182			}
1183			entries = append(entries, ceilingEntry{path: filepath.Clean(absoluteEntry), canonicalize: canonicalize})
1184		}
1185		if len(entries) == 0 {
1186			return discoverCheckoutRoot(dir)
1187		}
1188	
1189		resolver, resolution := sem.NewGitCeilingPathResolver(abs)
1190		if resolution != sem.GitCeilingPathResolved {
1191			if resolution != sem.GitCeilingPathUnsupported {
1192				return "", false
1193			}
1194			// Platforms without a safe mount inventory retain the prior lexical
1195			// behavior only when the caller put every usable entry after the
1196			// empty marker and therefore promised that none needs resolution.
1197			var ceilings []string
1198			for _, entry := range entries {
1199				if entry.canonicalize {
1200					return "", false
1201				}
1202				ceilings = append(ceilings, entry.path)
1203			}
1204			return discoverImplicitCheckoutRootBelowCeilings(abs, abs, ceilings, nil)
1205		}
1206		defer resolver.Close()
1207	
1208		physicalAbs, resolution := resolver.Canonicalize(abs)
1209		if resolution != sem.GitCeilingPathResolved {
1210			return "", false
1211		}
1212		ceilings := make([]string, 0, len(entries))
1213		for _, entry := range entries {
1214			ceiling := entry.path
1215			if entry.canonicalize {
1216				resolved, resolution := resolver.Canonicalize(ceiling)
1217				switch resolution {
1218				case sem.GitCeilingPathResolved:
1219					ceiling = resolved
1220				case sem.GitCeilingPathUnresolvable:
1221					continue
1222				default:
1223					// Exact Git parity would require following the unsafe path to
1224					// learn whether it aliases an ancestor. Refuse implicit
1225					// discovery rather than risk either network I/O or walking
1226					// through a boundary whose canonical spelling is unknown.
1227					return "", false
1228				}
1229			}
1230			ceilings = append(ceilings, ceiling)
1231		}
1232		return discoverImplicitCheckoutRootBelowCeilings(abs, physicalAbs, ceilings, resolver)
1233	}
1234	
1235	func discoverImplicitCheckoutRootBelowCeilings(namedStart, physicalStart string, ceilings []string, resolver *sem.GitCeilingPathResolver) (string, bool) {
1236		applicable := ceilings[:0]
1237		for _, ceiling := range ceilings {
1238			rel, err := filepath.Rel(ceiling, physicalStart)
1239			if err == nil && rel != "." && rel != ".." && !strings.HasPrefix(rel, ".."+string(filepath.Separator)) && !filepath.IsAbs(rel) {
1240				applicable = append(applicable, ceiling)
1241			}
1242		}
1243		abs := physicalStart
1244		for {
1245			for _, ceiling := range applicable {
1246				equal := abs == ceiling
1247				if runtime.GOOS == "windows" {
1248					equal = strings.EqualFold(abs, ceiling)
1249				}
1250				if equal {
1251					return "", false
1252				}
1253			}
1254			if resolver == nil {
1255				if _, err := os.Lstat(filepath.Join(abs, ".git")); err == nil {
1256					return abs, true
1257				}
1258			} else {
1259				exists, resolution := resolver.HasGitEntry(abs)
1260				if resolution != sem.GitCeilingPathResolved {
1261					return "", false
1262				}
1263				if exists {
1264					return preferredCheckoutRootSpelling(resolver, namedStart, abs)
1265				}
1266			}
1267			parent := filepath.Dir(abs)
1268			if parent == abs {
1269				return "", false
1270			}
1271			abs = parent
1272		}
1273	}
1274	
1275	// preferredCheckoutRootSpelling preserves the caller-visible spelling used by
1276	// the filesystem fallback when it names the physical checkout Git discovery
1277	// found. This matters on systems such as macOS where /var is an alias for
1278	// /private/var: ceilings must be compared physically, but an unrelated ceiling
1279	// must not silently change the checkout path returned to existing callers.
1280	func preferredCheckoutRootSpelling(resolver *sem.GitCeilingPathResolver, namedStart, physicalRoot string) (string, bool) {
1281		for candidate := namedStart; ; candidate = filepath.Dir(candidate) {
1282			resolved, resolution := resolver.Canonicalize(candidate)
1283			if resolution == sem.GitCeilingPathUnsafe {
1284				return "", false
1285			}
1286			equal := resolved == physicalRoot
1287			if runtime.GOOS == "windows" {
1288				equal = strings.EqualFold(resolved, physicalRoot)
1289			}
1290			if resolution == sem.GitCeilingPathResolved && equal {
1291				return candidate, true
1292			}
1293			parent := filepath.Dir(candidate)
1294			if parent == candidate {
1295				return physicalRoot, true
1296			}
1297		}
1298	}
1299	
1300	func analyzeAndPrint(ctx context.Context, opts Options, repo, base, head string, paths []string, flags commonFlags) error {
1301		maxSeconds := flags.MaxSeconds
1302		if maxSeconds < 0 {
1303			maxSeconds = defaultMaxSeconds
1304		}
1305		analyzeOptions := sem.AnalyzeOptions{
1306			MaxDuration: time.Duration(maxSeconds) * time.Second,
1307		}
1308		if flags.Progress {
1309			analyzeOptions.Progress = func(event sem.AnalyzeProgressEvent) {
1310				fmt.Fprintln(opts.Stderr, diffProgressLine(event))
1311			}
1312		}
1313		result, err := sem.AnalyzeGitRangeWithOptions(ctx, repo, base, head, paths, analyzeOptions)
1314		if err != nil {
1315			return err
1316		}
1317		return printResult(opts.Stdout, result, flags.JSON, opts.Version)
1318	}
1319	
1320	// diffProgressLine renders one --progress event for stderr.
1321	//
1322	// It is a named function rather than an inline closure because of the escaping:
1323	// event.Path is a raw Git pathname carried through from `git diff -z`, which may
1324	// hold any byte but NUL and '/', and this is the one sink that has to escape by
1325	// value instead of by wrapping its writer — stderr also carries the progress
1326	// bar's own cursor control (see progressbar.go), which a wrap could not tell
1327	// apart from an injected sequence.
1328	func diffProgressLine(event sem.AnalyzeProgressEvent) string {
1329		line := fmt.Sprintf("graph diff progress phase=%s files=%d/%d elapsed=%s",
1330			event.Phase,
1331			event.FilesDone,
1332			event.FilesTotal,
1333			event.Elapsed.Round(time.Millisecond),
1334		)
1335		if event.Path != "" {
1336			line += " file=" + termsafe.Line(event.Path)
1337		}
1338		return line
1339	}
1340	
1341	func printResult(out io.Writer, result sem.Result, asJSON bool, producerVersion string) error {
1342		// ProducerVersion is set here, the one place a Result is rendered, rather
1343		// than at each of the two callers — it needs the CLI's build-time version
1344		// (Options.Version), which the sem package that builds the rest of the
1345		// Result has no access to.
1346		result.ProducerVersion = producerVersion
1347		if asJSON {
1348			encoded, err := json.MarshalIndent(result, "", "  ")
1349			if err != nil {
1350				return err
1351			}
1352			fmt.Fprintln(termsafe.NewJSONWriter(out), string(encoded))
1353			return nil
1354		}
1355		sem.WriteText(out, result)
1356		return nil
1357	}
